[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    private static readonly List<Product> _products = new();

    [HttpGet("{id}")]
    public ActionResult<Product> Get(int id)
    {
        var product = _products.FirstOrDefault(p => p.Id == id);
        if (product == null)
            return NotFound();
        return Ok(product);
    }

    [HttpPost]
    public ActionResult<Product> Create(Product product)
    {
        product.Id = _products.Count + 1;
        _products.Add(product);
        return CreatedAtAction(nameof(Get), new { id = product.Id }, product);
    }

    [HttpDelete("{id}")]
    public IActionResult Delete(int id)
    {
        var removed = _products.RemoveAll(p => p.Id == id) > 0;
        return removed ? NoContent() : NotFound();
    }
}

[ApiController]
[Route("api/[controller]")]
public class ReportsController : ControllerBase
{
    [HttpGet("{id}")]
    public IActionResult GetReport(int id, string format = "json")
    {
        var data = new { Id = id, Name = "Sales Report" };

        return format.ToLower() switch
        {
            "xml" => Content(System.Text.Json.JsonSerializer.Serialize(data),
                "application/xml"),
            "csv" => File("Id,Name\n1,Sales Report", "text/csv",
                $"report-{id}.csv"),
            _ => Ok(data)
        };
    }

    [HttpGet("download/{id}")]
    public IActionResult Download(int id)
    {
        var bytes = System.Text.Encoding.UTF8.GetBytes("report content");
        return File(bytes, "application/pdf", $"report-{id}.pdf");
    }
}
